31	namespace trt_edgellm
32	{
33	
34	// Define missing constants for half precision
35	#ifndef HALF_FLT_MAX
36	#define HALF_FLT_MAX 65504.0f
37	#endif
38	
39	// Internal workspace structure for memory management (FP32 only)
40	struct SamplingWorkspace
41	{
42	    void* ptr;
43	    size_t size;
44	
45	    // Buffer pointers and sizes for different sampling methods
46	    float* topkTempLogits;
47	    int32_t* topkIndices;
48	    float* topkValues;
49	
50	    void* toppTempStorage; // Keep as void* for CUB temp storage
51	    float* toppProbs;
52	    float* toppSortedProbs;
53	    int32_t* toppSortedIdVals;
54	    int32_t* toppIdVals;
55	    int32_t* toppOffsetBuf;
56	    int32_t* toppBeginOffsetBuf;
57	    int32_t* toppTopKIndices;
58	    float* toppTopKValues;
59	    int32_t* toppEarlyExitFlags;
60	
61	    SamplingWorkspace()
62	        : ptr(nullptr)
63	        , size(0)
64	        , topkTempLogits(nullptr)
65	        , topkIndices(nullptr)
66	        , topkValues(nullptr)
67	        , toppTempStorage(nullptr)
68	        , toppProbs(nullptr)
69	        , toppSortedProbs(nullptr)
70	        , toppSortedIdVals(nullptr)
71	        , toppIdVals(nullptr)
72	        , toppOffsetBuf(nullptr)
73	        , toppBeginOffsetBuf(nullptr)
74	        , toppTopKIndices(nullptr)
75	        , toppTopKValues(nullptr)
76	        , toppEarlyExitFlags(nullptr)
77	    {
78	    }
79	
80	    // Calculate workspace partitioning for given parameters
81	    void setupWorkspace(void* workspace, size_t workspaceSize, SamplingParams const& params)
82	    {
83	        ptr = workspace;
84	        size = workspaceSize;
85	
86	        // Add alignment function (same as in size calculation)
87	        auto alignSize = [](size_t size) -> size_t {
88	            size_t const alignment = 256; // 256-byte alignment for optimal GPU memory access
89	            return (size + alignment - 1) & ~(alignment - 1);
90	        };
91	
92	        // Calculate buffer sizes and offsets
93	        size_t offset = 0;
94	
95	        if (params.useTopK)
96	        {
97	            // Top-K workspace layout
98	            size_t tempLogitsSize = alignSize(params.batchSize * params.vocabSize * sizeof(float));
99	            size_t indicesSize = alignSize(params.batchSize * 8 * params.topK * sizeof(int32_t)); // BLOCKS_PER_BEAM = 8
100	            size_t valuesSize = alignSize(params.batchSize * 8 * params.topK * sizeof(float));
101	
102	            topkTempLogits = reinterpret_cast<float*>(static_cast<char*>(ptr) + offset);
103	            offset += tempLogitsSize;
104	
105	            topkIndices = reinterpret_cast<int32_t*>(static_cast<char*>(ptr) + offset);
106	            offset += indicesSize;
107	
108	            topkValues = reinterpret_cast<float*>(static_cast<char*>(ptr) + offset);
109	            offset += valuesSize;
110	        }
111	        else if (params.useTopP)
112	        {
113	            // Top-P workspace layout
114	            // Calculate CUB temp storage size
115	            size_t cubTempStorageSize;
116	            cub::DeviceSegmentedRadixSort::SortPairsDescending(nullptr, cubTempStorageSize,
117	                static_cast<float*>(nullptr), static_cast<float*>(nullptr), static_cast<int32_t*>(nullptr),
118	                static_cast<int32_t*>(nullptr), static_cast<int32_t>(params.vocabSize * params.batchSize),
119	                params.batchSize, static_cast<int32_t*>(nullptr), static_cast<int32_t*>(nullptr));
120	
121	            toppTempStorage = static_cast<char*>(ptr) + offset;
122	            offset += alignSize(cubTempStorageSize);
123	
124	            toppProbs = reinterpret_cast<float*>(static_cast<char*>(ptr) + offset);
125	            offset += alignSize(params.batchSize * params.vocabSize * sizeof(float));
126	
127	            toppSortedProbs = reinterpret_cast<float*>(static_cast<char*>(ptr) + offset);
128	            offset += alignSize(params.batchSize * params.vocabSize * sizeof(float));
129	
130	            toppSortedIdVals = reinterpret_cast<int32_t*>(static_cast<char*>(ptr) + offset);
131	            offset += alignSize(params.batchSize * params.vocabSize * sizeof(int32_t));
132	
133	            toppIdVals = reinterpret_cast<int32_t*>(static_cast<char*>(ptr) + offset);
134	            offset += alignSize(params.batchSize * params.vocabSize * sizeof(int32_t));
135	
136	            toppOffsetBuf = reinterpret_cast<int32_t*>(static_cast<char*>(ptr) + offset);
137	            offset += alignSize((params.batchSize + 1) * sizeof(int32_t));
138	
139	            toppBeginOffsetBuf = reinterpret_cast<int32_t*>(static_cast<char*>(ptr) + offset);
140	            offset += alignSize((params.batchSize + 1) * sizeof(int32_t));
141	
142	            toppTopKIndices = reinterpret_cast<int32_t*>(static_cast<char*>(ptr) + offset);
143	            offset += alignSize(params.batchSize * params.vocabSize * sizeof(int32_t));
144	
145	            toppTopKValues = reinterpret_cast<float*>(static_cast<char*>(ptr) + offset);
146	            offset += alignSize(params.batchSize * params.vocabSize * sizeof(float));
147	
148	            toppEarlyExitFlags = reinterpret_cast<int32_t*>(static_cast<char*>(ptr) + offset);
149	            offset += alignSize(params.batchSize * sizeof(int32_t));
150	        }
151	
152	        // Validate workspace size
153	        ELLM_CHECK(offset <= workspaceSize,
154	            "Workspace size too small. Required: " + std::to_string(offset)
155	                + ", provided: " + std::to_string(workspaceSize));
156	    }
157	
158	    // Setup workspace for selectAllTopK
159	    void setupWorkspaceForTopK(
160	        void* workspace, size_t workspaceSize, int32_t batchSize, int32_t vocabSize, int32_t topK)
161	    {
162	        ptr = workspace;
163	        size = workspaceSize;
164	
165	        // Add alignment function (same as in size calculation)
166	        auto alignSize = [](size_t size) -> size_t {
167	            size_t const alignment = 256; // 256-byte alignment for optimal GPU memory access
168	            return (size + alignment - 1) & ~(alignment - 1);
169	        };
170	
171	        size_t offset = 0;
172	
173	        // Same layout as top-K sampling
174	        size_t tempLogitsSize = alignSize(batchSize * vocabSize * sizeof(float));
175	        size_t indicesSize = alignSize(batchSize * 8 * topK * sizeof(int32_t)); // BLOCKS_PER_BEAM = 8
176	        size_t valuesSize = alignSize(batchSize * 8 * topK * sizeof(float));
177	
178	        topkTempLogits = reinterpret_cast<float*>(static_cast<char*>(ptr) + offset);
179	        offset += tempLogitsSize;
180	
181	        topkIndices = reinterpret_cast<int32_t*>(static_cast<char*>(ptr) + offset);
182	        offset += indicesSize;
183	
184	        topkValues = reinterpret_cast<float*>(static_cast<char*>(ptr) + offset);
185	        offset += valuesSize;
186	
187	        // Validate workspace size
188	        ELLM_CHECK(offset <= workspaceSize,
189	            "Workspace size too small for topK. Required: " + std::to_string(offset)
190	                + ", provided: " + std::to_string(workspaceSize));
191	    }
192	};
193	
194	// ========================================================================
195	// WORKSPACE SIZE CALCULATION
196	// ========================================================================
197	
198	// Enhanced workspace size calculation that handles alignment (FP32 only)
199	size_t getTopKtopPSamplingWorkspaceSize(int32_t batchSize, int32_t vocabSize, SamplingParams const& params)
200	{
201	    size_t workspaceSize = 0;
202	
203	    // Add alignment padding between buffers
204	    auto alignSize = [](size_t size) -> size_t {
205	        size_t const alignment = 256; // 256-byte alignment for optimal GPU memory access
206	        return (size + alignment - 1) & ~(alignment - 1);
207	    };
208	
209	    if (params.useTopK)
210	    {
211	        workspaceSize += alignSize(batchSize * vocabSize * sizeof(float));         // temp logits
212	        workspaceSize += alignSize(batchSize * 8 * params.topK * sizeof(int32_t)); // top-k indices
213	        workspaceSize += alignSize(batchSize * 8 * params.topK * sizeof(float));   // top-k values
214	    }
215	    else if (params.useTopP)
216	    {
217	        // Calculate CUB temp storage size
218	        size_t cubTempStorageSize;
219	        cub::DeviceSegmentedRadixSort::SortPairsDescending(nullptr, cubTempStorageSize, static_cast<float*>(nullptr),
220	            static_cast<float*>(nullptr), static_cast<int32_t*>(nullptr), static_cast<int32_t*>(nullptr),
221	            static_cast<int32_t>(vocabSize * batchSize), batchSize, static_cast<int32_t*>(nullptr),
222	            static_cast<int32_t*>(nullptr));
223	
224	        workspaceSize += alignSize(cubTempStorageSize);                      // CUB temp storage
225	        workspaceSize += alignSize(batchSize * vocabSize * sizeof(float));   // probs
226	        workspaceSize += alignSize(batchSize * vocabSize * sizeof(float));   // sorted probs
227	        workspaceSize += alignSize(batchSize * vocabSize * sizeof(int32_t)); // sorted id vals
228	        workspaceSize += alignSize(batchSize * vocabSize * sizeof(int32_t)); // id vals
229	        workspaceSize += alignSize((batchSize + 1) * sizeof(int32_t));       // offset buf
230	        workspaceSize += alignSize((batchSize + 1) * sizeof(int32_t));       // begin offset buf
231	        workspaceSize += alignSize(batchSize * vocabSize * sizeof(int32_t)); // top-k indices
232	        workspaceSize += alignSize(batchSize * vocabSize * sizeof(float));   // top-k values
233	        workspaceSize += alignSize(batchSize * sizeof(int32_t));             // early exit flags
234	    }
235	    else
236	    {
237	        // No filtering - error out
238	        throw std::runtime_error("Either topK or topP must be set");
239	    }
240	
241	    return workspaceSize;
242	}
