244	// Calculate workspace size for selectAllTopK (FP32 only)
245	size_t getSelectAllTopKWorkspaceSize(int32_t batchSize, int32_t vocabSize, int32_t topK) noexcept
246	{
247	    auto alignSize = [](size_t size) -> size_t {
248	        size_t const alignment = 256;
249	        return (size + alignment - 1) & ~(alignment - 1);
250	    };
251	
252	    size_t workspaceSize = 0;
253	    workspaceSize += alignSize(batchSize * vocabSize * sizeof(float));  // temp logits
254	    workspaceSize += alignSize(batchSize * 8 * topK * sizeof(int32_t)); // top-k indices
255	    workspaceSize += alignSize(batchSize * 8 * topK * sizeof(float));   // top-k values
256	
257	    return workspaceSize;
258	}
