276	// Helper structures for top-k reduction operations (FP32 only)
277	struct TopK_2
278	{
279	    float value;
280	    int32_t index;
281	
282	    __device__ __forceinline__ void init()
283	    {
284	        value = -FLT_MAX;
285	        index = -1;
286	    }
287	
288	    __device__ __forceinline__ void insert(float elem, int32_t elemId)
289	    {
290	        if (elem > value)
291	        {
292	            value = elem;
293	            index = elemId;
294	        }
295	    }
296	};
297	
298	struct maxOpFunctor
299	{
300	    __device__ __forceinline__ float operator()(float const& a, float const& b) const
301	    {
302	        return a > b ? a : b;
303	    }
304	};
305	
306	struct sumOpFunctor
307	{
308	    __device__ __forceinline__ float operator()(float const& a, float const& b) const
309	    {
310	        return a + b;
311	    }
312	};
313	
314	// Reduction operator for top-k (FP32 only)
315	struct topk2MaxOpFunctor
316	{
317	    __device__ __forceinline__ TopK_2 operator()(TopK_2 const& a, TopK_2 const& b) const
318	    {
319	        return a.value > b.value ? a : b;
320	    }
321	};
