323	// Stage 2 kernel for returnAllTopK - returns indices and raw values only (no transformations)
324	template <int BLOCK_SIZE>
325	__global__ void topKStage2ReturnAllTopK(int32_t const* __restrict topKTmpIdBuf, float* topKTmpValBuf,
326	    int32_t* outputIndices, float* outputValues, int32_t batchSize, int32_t vocabSize, int32_t topK,
327	    int32_t blocksPerBeam)
328	{
329	    auto const tid = static_cast<int32_t>(threadIdx.x);
330	    auto const batchIdx = static_cast<int32_t>(blockIdx.x);
331	
332	    if (batchIdx >= batchSize)
333	        return;
334	
335	    auto const size = topK * blocksPerBeam;
336	    auto const stride = topK * blocksPerBeam;
337	
338	    typedef cub::BlockReduce<TopK_2, BLOCK_SIZE> BlockReduce;
339	    __shared__ typename BlockReduce::TempStorage tempStorage;
340	    extern __shared__ char array[];
341	    float* sVal = topKTmpValBuf + batchIdx * stride;
342	    auto* sId = reinterpret_cast<int32_t*>(array);
343	    auto sValSelected = reinterpret_cast<float*>(sId + topK);
344	
345	    TopK_2 partial;
346	
347	    // Iteratively find top-K elements by max value
348	    for (int32_t ite = 0; ite < topK; ite++)
349	    {
350	        partial.init();
351	#pragma unroll
352	        for (int32_t i = tid; i < size; i += BLOCK_SIZE)
353	        {
354	            partial.insert(sVal[i], i);
355	        }
356	
357	        TopK_2 total = BlockReduce(tempStorage).Reduce(partial, topk2MaxOpFunctor());
358	
359	        if (tid == 0)
360	        {
361	            sId[ite] = total.index;
362	            sValSelected[ite] = total.value; // Store original value
363	            sVal[total.index] = -FLT_MAX;    // Mask out selected element for next iteration
364	        }
365	        __syncthreads();
366	    }
367	
368	    // Write outputs - return indices and original values only
369	    if (tid == 0)
370	    {
371	        for (int32_t ki = 0; ki < topK; ki++)
372	        {
373	            auto originalValue = sValSelected[ki];
374	            auto idx = sId[ki];
375	
376	            if (outputIndices != nullptr)
377	            {
378	                auto outputId = idx != -1 ? topKTmpIdBuf[batchIdx * stride + idx] % vocabSize : vocabSize - 1;
379	                outputId = outputId == -1 ? vocabSize - 1 : outputId;
380	                outputIndices[batchIdx * topK + ki] = outputId;
381	            }
382	
383	            if (outputValues != nullptr)
384	            {
385	                // Return original raw value from input (no transformation)
386	                outputValues[batchIdx * topK + ki] = originalValue;
387	            }
388	        }
389	    }
390	}
