392	// Block prefix callback for cumulative sum computation
393	struct BlockPrefixCallbackOp
394	{
395	    float runningTotal;
396	
397	    __device__ BlockPrefixCallbackOp(float runningTotal)
398	        : runningTotal(runningTotal)
399	    {
400	    }
401	
402	    __device__ float operator()(float blockAggregate)
403	    {
404	        float oldPrefix = runningTotal;
405	        runningTotal += blockAggregate;
406	        return oldPrefix;
407	    }
408	};
