410	// =======================================================================================
411	// TOP-K SAMPLING KERNELS (Based on TensorRT-LLM two-stage approach)
412	// =======================================================================================
413	
414	// Stage 1: Find top-K elements using iterative block-level reduction (FP32 only)
415	template <int32_t BLOCK_SIZE_, int32_t BLOCKS_PER_BEAM_>
416	__global__ void topKStage1(float const* __restrict__ logits, float* tmpLogits, int32_t* topKTmpIdBuf,
417	    float* topKTmpValBuf, SamplingParams const params)
418	{
419	    typedef cub::BlockReduce<TopK_2, BLOCK_SIZE_> BlockReduce;
420	    __shared__ typename BlockReduce::TempStorage tempStorage;
421	
422	    auto const tid = static_cast<int32_t>(threadIdx.x);
423	    auto const bid = static_cast<int32_t>(blockIdx.x);
424	
425	    auto const batchId = bid / BLOCKS_PER_BEAM_;
426	    auto const blockLane = bid % BLOCKS_PER_BEAM_;
427	
428	    if (batchId >= params.batchSize)
429	        return;
430	
431	    auto const vocabSize = params.vocabSize;
432	    auto const k = params.topK;
433	    auto const temperature = params.temperature;
434	    auto const invTemp = invTemp_device(temperature);
435	
436	    auto const tmpLogBufIndex = batchId * vocabSize;
437	    auto const tmpTopKBufIndex = batchId * BLOCKS_PER_BEAM_ * k + blockLane * k;
438	
439	    TopK_2 partial;
440	    float const MAX_T_VAL = FLT_MAX;
441	
442	    // Copy logits to temporary buffer and apply temperature
443	    for (auto elemId = tid + blockLane * BLOCK_SIZE_; elemId < vocabSize; elemId += BLOCK_SIZE_ * BLOCKS_PER_BEAM_)
444	    {
445	        auto localIndex = elemId + tmpLogBufIndex;
446	        float logit = logits[localIndex];
447	        tmpLogits[localIndex] = logit * invTemp;
448	    }
449	
450	    // Find top-K elements iteratively
451	    for (int32_t ite = 0; ite < k; ite++)
452	    {
453	        partial.init();
454	#pragma unroll
455	        for (auto elemId = tid + blockLane * BLOCK_SIZE_; elemId < vocabSize; elemId += BLOCK_SIZE_ * BLOCKS_PER_BEAM_)
456	        {
457	            auto index = elemId + tmpLogBufIndex;
458	            partial.insert(tmpLogits[index], index);
459	        }
460	
461	        TopK_2 total = BlockReduce(tempStorage).Reduce(partial, topk2MaxOpFunctor());
462	
463	        if (tid == 0)
464	        {
465	            auto const index = tmpTopKBufIndex + ite;
466	            topKTmpIdBuf[index] = total.index;
467	            topKTmpValBuf[index] = total.value;
468	
469	            if (total.index >= 0)
470	            {
471	                tmpLogits[total.index] = -MAX_T_VAL;
472	            }
473	        }
474	        __syncthreads();
475	    }
476	}
477	
478	// Stage 2: Sample from top-K elements using softmax (FP32 only)
479	template <int BLOCK_SIZE_>
480	__global__ void topKStage2Sampling(int32_t const* __restrict__ topKTmpIdBuf, float* topKTmpValBuf,
481	    int32_t* __restrict__ selectedIndices, SamplingParams const params, uint64_t philoxSeed, uint64_t philoxOffset)
482	{
483	    float const MAX_T_VAL = FLT_MAX;
484	
485	    auto const tid = static_cast<int32_t>(threadIdx.x);
486	    auto const batchIdx = static_cast<int32_t>(blockIdx.x);
487	
488	    if (batchIdx >= params.batchSize)
489	    {
490	        return;
491	    }
492	
493	    auto const k = params.topK;
494	    auto const topP = params.topP;
495	    auto const size = k * 8; // BLOCKS_PER_BEAM = 8
496	    auto const stride = k * 8;
497	
498	    typedef cub::BlockReduce<TopK_2, BLOCK_SIZE_> BlockReduce;
499	    __shared__ typename BlockReduce::TempStorage tempStorage;
500	    extern __shared__ char array[];
501	    __shared__ float sSum;
502	    float* sVal = topKTmpValBuf + batchIdx * stride;
503	    auto* sId = reinterpret_cast<int32_t*>(array);
504	
505	    if (tid == 0)
506	    {
507	        sSum = 0.0f;
508	    }
509	    TopK_2 partial;
510	
511	    auto sVal2 = reinterpret_cast<float*>(sId + k);
512	    float maxLogit;
513	
514	    // Sort top-K elements and compute softmax
515	    for (int32_t ite = 0; ite < k; ite++)
516	    {
517	        partial.init();
518	#pragma unroll
519	        for (int32_t i = tid; i < size; i += BLOCK_SIZE_)
520	        {
521	            partial.insert(sVal[i], i);
522	        }
523	
524	        TopK_2 total = BlockReduce(tempStorage).Reduce(partial, topk2MaxOpFunctor());
525	
526	        if (tid == 0)
527	        {
528	            if (ite == 0)
529	            {
530	                maxLogit = total.value;
531	            }
532	
533	            if (total.index >= 0 && total.index < size)
534	            {
535	                sId[ite] = total.index;
536	                sVal[total.index] = -MAX_T_VAL;
537	
538	                total.value = __expf(total.value - maxLogit);
539	                sVal2[ite] = total.value;
540	                sSum += total.value;
541	            }
542	            else
543	            {
544	                sId[ite] = -1;
545	                sVal2[ite] = 0.0f;
546	            }
547	        }
548	        __syncthreads();
549	    }
550	
551	    // Sample from the distribution
552	    if (tid == 0)
553	    {
554	        // Initialize curand state for this batch
555	        curandState_t localState;
556	        curand_init(philoxSeed, batchIdx, philoxOffset, &localState);
557	
558	        // When generating random number, topP filtering is applied to ensure the sum of the probabilities is less than
559	        // topP
560	        auto randNum = static_cast<float>(curand_uniform(&localState) * topP * sSum);
561	
562	        for (int32_t ki = 0; ki < k; ki++)
563	        {
564	            auto expLogit = sVal2[ki];
565	            randNum = randNum - expLogit;
566	
567	            if (randNum <= 0.0f || ki == k - 1)
568	            {
569	                auto idx = sId[ki];
570	
571	                if (idx >= 0 && idx < stride)
572	                {
573	                    auto globalIdx = topKTmpIdBuf[batchIdx * stride + idx];
574	                    auto outputId = (globalIdx != -1) ? (globalIdx % params.vocabSize) : (params.vocabSize - 1);
575	                    outputId = (outputId == -1) ? (params.vocabSize - 1) : outputId;
576	
577	                    if (outputId >= 0 && outputId < params.vocabSize)
578	                    {
579	                        selectedIndices[batchIdx] = outputId;
580	                    }
581	                    else
582	                    {
583	                        selectedIndices[batchIdx] = params.vocabSize - 1; // Safe fallback
584	                    }
585	                }
586	                else
587	                {
588	                    selectedIndices[batchIdx] = params.vocabSize - 1; // Safe fallback
589	                }
590	                break;
591	            }
592	        }
593	    }
594	}
595	
596	// Unified softmax / log-softmax kernel.
597	// LOG_OUTPUT=false: output[i] = exp(x[i]*invT - max) / sum_exp  (probabilities for sampling)
598	// LOG_OUTPUT=true:  output[i] = x[i]*invT - max - log(sum_exp)  (log-probabilities, T=1 for logprobs)
599	// Use customed reductionOp to WAR CUDA12/13 compatibility issue
600	template <int BLOCK_SIZE, bool LOG_OUTPUT>
601	__global__ void softmaxKernelImpl(
602	    float const* logits, float* output, int32_t batchSize, int32_t vocabSize, float temperature)
603	{
604	    auto const batchId = static_cast<int32_t>(blockIdx.x);
605	    auto const tid = static_cast<int32_t>(threadIdx.x);
606	
607	    if (batchId >= batchSize)
608	        return;
609	
610	    auto const offset = batchId * vocabSize;
611	    auto const invTemp = invTemp_device(temperature);
612	
613	    typedef cub::BlockReduce<float, BLOCK_SIZE> BlockReduce;
614	    __shared__ typename BlockReduce::TempStorage tempStorage;
615	    __shared__ float sharedMax;
616	    __shared__ float sharedAgg; // sum_exp (softmax) or log(sum_exp) (log-softmax)
617	
618	    // Pass 1: find max for numerical stability
619	    float threadMax = -FLT_MAX;
620	    for (int32_t i = tid; i < vocabSize; i += BLOCK_SIZE)
621	        threadMax = fmaxf(threadMax, logits[offset + i] * invTemp);
622	    float blockMax = BlockReduce(tempStorage).Reduce(threadMax, maxOpFunctor());
623	    if (tid == 0)
624	    {
625	        sharedMax = blockMax;
626	        sharedAgg = 0.0f;
627	    }
628	    __syncthreads();
629	
630	    // Pass 2: compute exp(x*invT - max), store intermediates for softmax, accumulate sum
631	    float threadSum = 0.0f;
632	    for (int32_t i = tid; i < vocabSize; i += BLOCK_SIZE)
633	    {
634	        float expVal = expf(logits[offset + i] * invTemp - sharedMax);
635	        if constexpr (!LOG_OUTPUT)
636	            output[offset + i] = expVal; // store for in-place normalization in pass 3
637	        threadSum += expVal;
638	    }
639	    float blockSum = BlockReduce(tempStorage).Reduce(threadSum, sumOpFunctor());
640	    if (tid == 0)
641	        sharedAgg = LOG_OUTPUT ? logf(blockSum) : blockSum;
642	    __syncthreads();
643	
644	    // Pass 3: write final output
645	    for (int32_t i = tid; i < vocabSize; i += BLOCK_SIZE)
646	    {
647	        if constexpr (LOG_OUTPUT)
648	            output[offset + i] = logits[offset + i] * invTemp - sharedMax - sharedAgg;
649	        else
650	            output[offset + i] /= sharedAgg;
651	    }
652	}
