654	__global__ void applyLogitBiasKernel(
655	    float* logits, int32_t const* tokenIds, float const* biasValues, int32_t const* offsets, int32_t vocabSize)
656	{
657	    int32_t const batchId = static_cast<int32_t>(blockIdx.x);
658	    int32_t const begin = offsets[batchId];
659	    int32_t const end = offsets[batchId + 1];
660	    float* rowLogits = logits + static_cast<int64_t>(batchId) * vocabSize;
661	
662	    for (int32_t entryIdx = begin + static_cast<int32_t>(threadIdx.x); entryIdx < end;
663	        entryIdx += static_cast<int32_t>(blockDim.x))
664	    {
665	        int32_t const tokenId = tokenIds[entryIdx];
666	        if (tokenId >= 0 && tokenId < vocabSize)
667	        {
668	            rowLogits[tokenId] += biasValues[entryIdx];
669	        }
670	    }
671	}
