673	void applyLogitBias(rt::Tensor& logits, rt::Tensor const& tokenIds, rt::Tensor const& biasValues,
674	    rt::Tensor const& offsets, cudaStream_t stream)
675	{
676	    check::check(logits.getDeviceType() == rt::DeviceType::kGPU && tokenIds.getDeviceType() == rt::DeviceType::kGPU
677	            && biasValues.getDeviceType() == rt::DeviceType::kGPU && offsets.getDeviceType() == rt::DeviceType::kGPU,
678	        "All tensors must be on GPU");
679	    check::check(logits.getDataType() == nvinfer1::DataType::kFLOAT
680	            && tokenIds.getDataType() == nvinfer1::DataType::kINT32
681	            && biasValues.getDataType() == nvinfer1::DataType::kFLOAT
682	            && offsets.getDataType() == nvinfer1::DataType::kINT32,
683	        "Invalid tensor data types");
684	
685	    auto const logitsShape = logits.getShape();
686	    auto const tokenIdsShape = tokenIds.getShape();
687	    auto const biasValuesShape = biasValues.getShape();
688	    auto const offsetsShape = offsets.getShape();
689	
690	    check::check(logitsShape.getNumDims() == 2 && tokenIdsShape.getNumDims() == 1 && biasValuesShape.getNumDims() == 1
691	            && offsetsShape.getNumDims() == 1,
692	        "Invalid tensor dimensions");
693	    check::check(tokenIdsShape[0] == biasValuesShape[0], "Logit bias token/value shape mismatch");
694	    check::check(offsetsShape[0] == logitsShape[0] + 1, "Logit bias offsets shape mismatch");
695	
696	    int32_t const batchSize = static_cast<int32_t>(logitsShape[0]);
697	    int32_t const vocabSize = static_cast<int32_t>(logitsShape[1]);
698	    int64_t const numBiasedTokens = tokenIdsShape[0];
699	    if (batchSize == 0 || vocabSize == 0 || numBiasedTokens == 0)
700	    {
701	        return;
702	    }
703	
704	    constexpr int32_t kBLOCK_SIZE = 256;
705	    applyLogitBiasKernel<<<batchSize, kBLOCK_SIZE, 0, stream>>>(logits.dataPointer<float>(),
706	        tokenIds.dataPointer<int32_t>(), biasValues.dataPointer<float>(), offsets.dataPointer<int32_t>(), vocabSize);
707	}
