709	// Initialize ID values and offsets for top-p sampling
710	__global__ void topPInitialize(
711	    int32_t* topPIdValBuf, int32_t* topPOffsetBuf, int32_t* beginTopPOffsetBuf, int32_t batchSize, int32_t vocabSize)
712	{
713	    auto const tid = static_cast<int32_t>(threadIdx.x);
714	    auto const bid = static_cast<int32_t>(blockIdx.x);
715	
716	    if (bid == 0)
717	    {
718	        for (auto i = tid; i < batchSize + 1; i += static_cast<int32_t>(blockDim.x))
719	        {
720	            int32_t expectedOffset = i * vocabSize;
721	            topPOffsetBuf[i] = expectedOffset;
722	            beginTopPOffsetBuf[i] = expectedOffset;
723	        }
724	    }
725	
726	    auto index = tid + bid * static_cast<int32_t>(blockDim.x);
727	
728	    while (index < batchSize * vocabSize)
729	    {
730	        topPIdValBuf[index] = index % vocabSize;
731	        index += static_cast<int32_t>(blockDim.x * gridDim.x);
732	    }
733	}
