735	// Early exit optimization: check if highest probability token exceeds threshold (FP32 only)
736	template <int THREADBLOCK_SIZE>
737	__launch_bounds__(THREADBLOCK_SIZE) __global__ void topPBeamTopKKernel(float const* probs, int32_t* topKTmpIdBuf,
738	    float* topKTmpValBuf, int32_t* earlyExitFlags, int32_t vocabSize, float topP, int32_t batchSize)
739	{
740	    auto const threadId = static_cast<int32_t>(threadIdx.x);
741	    auto const batchId = static_cast<int32_t>(blockIdx.x);
742	
743	    if (batchId >= batchSize)
744	        return;
745	
746	    float pThreshold = topP;
747	
748	    typedef cub::BlockReduce<TopK_2, THREADBLOCK_SIZE> BlockReduce;
749	    __shared__ typename BlockReduce::TempStorage temp_storage;
750	    TopK_2 partial;
751	
752	    float const MAX_T_VAL = FLT_MAX;
753	
754	    partial.value = -MAX_T_VAL;
755	    partial.index = -1;
756	
757	#pragma unroll
758	    for (int32_t elemId = static_cast<int32_t>(threadId); elemId < vocabSize; elemId += THREADBLOCK_SIZE)
759	    {
760	        auto index = elemId + batchId * vocabSize;
761	        partial.insert(probs[index], elemId);
762	    }
763	
764	    TopK_2 total = BlockReduce(temp_storage).Reduce(partial, topk2MaxOpFunctor());
765	
766	    if (threadId == 0)
767	    {
768	        float sumProb = total.value;
769	
770	        if (sumProb >= pThreshold)
771	        {
772	            // Early exit: set flag and store the selected token
773	            earlyExitFlags[batchId] = 1;
774	            auto index = batchId * vocabSize;
775	            topKTmpIdBuf[index] = total.index; // Store the actual token ID
776	            topKTmpValBuf[index] = total.value;
777	        }
778	        else
779	        {
780	            // No early exit
781	            earlyExitFlags[batchId] = 0;
782	        }
783	    }
784	}
785	
786	// Final sampling stage using block-level prefix sum
787	template <int blockSize>
788	__global__ void topPSampling(float const* sortedProbs, int32_t const* sortedIdVals, int32_t* selectedIndices,
789	    int32_t const* topKTmpIdBuf, int32_t const* earlyExitFlags, int32_t vocabSize, uint64_t philoxSeed,
790	    uint64_t philoxOffset, float topP, int32_t batchSize)
791	{
792	    __shared__ float randNumS;
793	
794	    auto const tid = static_cast<int32_t>(threadIdx.x);
795	    auto const batchId = static_cast<int32_t>(blockIdx.x);
796	
797	    if (batchId >= batchSize)
798	        return;
799	
800	    auto const probThreshold = topP;
801	
802	    if (threadIdx.x == 0)
803	    {
804	        // Initialize curand state for this batch
805	        curandState_t localState;
806	        curand_init(philoxSeed, batchId, philoxOffset, &localState);
807	
808	        auto const randomNumber = curand_uniform(&localState);
809	        randNumS = randomNumber * probThreshold;
810	    }
811	
812	    typedef cub::BlockScan<float, blockSize> BlockScan;
813	    __shared__ typename BlockScan::TempStorage tempStorage;
814	    BlockPrefixCallbackOp prefixOp(0);
815	
816	    __syncthreads();
817	
818	    auto offset = batchId * vocabSize;
819	    auto end = ((vocabSize + blockSize - 1) / blockSize) * blockSize;
820	    int32_t selectedTokenId = 0;
821	    float threadOffset = 0;
822	    int32_t count = 0;
823	
824	    for (int vi = tid; vi < end; vi += blockSize)
825	    {
826	        auto threadProb = (vi < vocabSize) ? (sortedProbs[offset + vi]) : 0.f;
827	        BlockScan(tempStorage).InclusiveSum(threadProb, threadOffset, prefixOp);
828	        count = __syncthreads_count(randNumS <= threadOffset);
829	        selectedTokenId = vi;
830	
831	        if (count != 0)
832	        {
833	            break;
834	        }
835	    }
836	
837	    selectedTokenId = min(selectedTokenId, vocabSize - 1);
838	
839	    if (threadIdx.x == min(blockDim.x - count, blockDim.x - 1))
840	    {
841	        int32_t finalToken = sortedIdVals[offset + selectedTokenId];
842	        selectedIndices[batchId] = finalToken;
843	    }
844	}
845	
846	// Updated sampling function with tensor-based interface (FP32 only)
847	void topKtopPSamplingFromLogits(rt::Tensor const& logits, rt::Tensor& selectedIndices, SamplingParams const& params,
848	    rt::Tensor& workspace, cudaStream_t stream, uint64_t philoxSeed, uint64_t philoxOffset)
849	{
850	    // Validate input tensors
851	    check::check(logits.getDeviceType() == rt::DeviceType::kGPU
852	            && selectedIndices.getDeviceType() == rt::DeviceType::kGPU
853	            && workspace.getDeviceType() == rt::DeviceType::kGPU,
854	        "All tensors must be on GPU");
855	    check::check(logits.getDataType() == nvinfer1::DataType::kFLOAT
856	            && selectedIndices.getDataType() == nvinfer1::DataType::kINT32
857	            && workspace.getDataType() == nvinfer1::DataType::kINT8,
858	        "Invalid tensor data types");
859	
860	    auto logitsShape = logits.getShape();
861	    auto selectedIndicesShape = selectedIndices.getShape();
862	    check::check(logitsShape.getNumDims() == 2 && selectedIndicesShape.getNumDims() == 2, "Invalid tensor dimensions");
863	    check::check(logitsShape[0] == params.batchSize && logitsShape[1] == params.vocabSize,
864	        "Logits tensor shape mismatch with parameters");
865	    check::check(selectedIndicesShape[0] == params.batchSize && selectedIndicesShape[1] == 1,
866	        "Selected indices tensor shape mismatch with parameters");
867	
868	    int const BLOCK_SIZE = 256;
869	    int const BLOCKS_PER_BEAM = 8;
870	
871	    // Setup workspace partitioning
872	    SamplingWorkspace ws;
873	    ws.setupWorkspace(workspace.rawPointer(), workspace.getMemoryCapacity(), params);
874	
875	    // Validate workspace buffers
876	    if (params.useTopK)
877	    {
878	        assert(ws.topkTempLogits != nullptr && ws.topkIndices != nullptr && ws.topkValues != nullptr);
879	    }
880	
881	    if (params.useTopK)
882	    {
883	
884	        // Stage 1: Find top-K elements
885	        dim3 grid1(params.batchSize * BLOCKS_PER_BEAM);
886	        dim3 block1(BLOCK_SIZE);
887	
888	        topKStage1<BLOCK_SIZE, BLOCKS_PER_BEAM><<<grid1, block1, 0, stream>>>(
889	            logits.dataPointer<float>(), ws.topkTempLogits, ws.topkIndices, ws.topkValues, params);
890	
891	        // Stage 2: Sample from top-K elements
892	        dim3 grid2(params.batchSize);
893	        dim3 block2(BLOCK_SIZE);
894	        size_t sharedMemSize = params.topK * sizeof(int32_t) + params.topK * sizeof(float);
895	
896	        topKStage2Sampling<BLOCK_SIZE><<<grid2, block2, sharedMemSize, stream>>>(
897	            ws.topkIndices, ws.topkValues, selectedIndices.dataPointer<int32_t>(), params, philoxSeed, philoxOffset);
898	    }
899	    else if (params.useTopP)
900	    {
901	        // Top-P only sampling using workspace
902	
903	        // Stage 0: Convert logits to probabilities using softmax
904	        int const SOFTMAX_BLOCK_SIZE = 256;
905	
906	        softmaxKernelImpl<SOFTMAX_BLOCK_SIZE, false><<<params.batchSize, SOFTMAX_BLOCK_SIZE, 0, stream>>>(
907	            logits.dataPointer<float>(), ws.toppProbs, params.batchSize, params.vocabSize, params.temperature);
908	
909	        // Stage 1: Initialize
910	        topPInitialize<<<32, 512, 0, stream>>>(
911	            ws.toppIdVals, ws.toppOffsetBuf, ws.toppBeginOffsetBuf, params.batchSize, params.vocabSize);
912	
913	        // Stage 2: Early exit optimization
914	        int const BLOCK_SIZE_TOPK = 256;
915	
916	        topPBeamTopKKernel<BLOCK_SIZE_TOPK><<<params.batchSize, BLOCK_SIZE_TOPK, 0, stream>>>(ws.toppProbs,
917	            ws.toppTopKIndices, ws.toppTopKValues, ws.toppEarlyExitFlags, params.vocabSize, params.topP,
918	            params.batchSize);
919	
920	        // Stage 3: Sort probabilities in descending order
921	        size_t cubTempStorageSize;
922	        cub::DeviceSegmentedRadixSort::SortPairsDescending(nullptr, cubTempStorageSize, static_cast<float*>(nullptr),
923	            static_cast<float*>(nullptr), static_cast<int32_t*>(nullptr), static_cast<int32_t*>(nullptr),
924	            static_cast<int32_t>(params.vocabSize * params.batchSize), params.batchSize, static_cast<int32_t*>(nullptr),
925	            static_cast<int32_t*>(nullptr));
926	
927	        cub::DeviceSegmentedRadixSort::SortPairsDescending(ws.toppTempStorage, cubTempStorageSize, ws.toppProbs,
928	            ws.toppSortedProbs, ws.toppIdVals, ws.toppSortedIdVals, params.vocabSize * params.batchSize,
929	            params.batchSize, ws.toppBeginOffsetBuf, ws.toppOffsetBuf + 1, 0, sizeof(float) * 8, stream);
930	
931	        // Stage 4: Sample using block-level prefix sum
932	        int const SAMPLING_BLOCK_SIZE = 256;
933	
934	        topPSampling<SAMPLING_BLOCK_SIZE><<<params.batchSize, SAMPLING_BLOCK_SIZE, 0, stream>>>(ws.toppSortedProbs,
935	            ws.toppSortedIdVals, selectedIndices.dataPointer<int32_t>(), ws.toppTopKIndices, ws.toppEarlyExitFlags,
936	            params.vocabSize, philoxSeed, philoxOffset, params.topP, params.batchSize);
937	    }
938	}
939	
940	void selectAllTopK(rt::Tensor const& input, rt::OptionalOutputTensor topKValues, rt::Tensor& topKIndices, int32_t topK,
941	    rt::Tensor& workspace, cudaStream_t stream)
942	{
943	    // Validate input tensors
944	    check::check(input.getDeviceType() == rt::DeviceType::kGPU && topKIndices.getDeviceType() == rt::DeviceType::kGPU
945	            && workspace.getDeviceType() == rt::DeviceType::kGPU,
946	        "All tensors must be on GPU");
947	    check::check(input.getDataType() == nvinfer1::DataType::kFLOAT
948	            && topKIndices.getDataType() == nvinfer1::DataType::kINT32
949	            && workspace.getDataType() == nvinfer1::DataType::kINT8,
950	        "Invalid tensor data types");
951	
952	    auto inputShape = input.getShape();
953	    auto topKIndicesShape = topKIndices.getShape();
954	    check::check(inputShape.getNumDims() == 2 && topKIndicesShape.getNumDims() == 2, "Invalid tensor dimensions");
955	
956	    int32_t batchSize = inputShape[0];
957	    int32_t vocabSize = inputShape[1];
958	
959	    check::check(topKIndicesShape[0] == batchSize && topKIndicesShape[1] == topK, "TopK indices tensor shape mismatch");
960	
961	    if (topKValues.has_value())
962	    {
963	        rt::Tensor& topKValuesTensor = topKValues.value().get();
964	        check::check(topKValuesTensor.getDeviceType() == rt::DeviceType::kGPU
965	                && topKValuesTensor.getDataType() == nvinfer1::DataType::kFLOAT,
966	            "TopK values tensor must be on GPU with float data type");
967	        auto topKValuesShape = topKValuesTensor.getShape();
968	        check::check(topKValuesShape.getNumDims() == 2 && topKValuesShape[0] == batchSize && topKValuesShape[1] == topK,
969	            "TopK values tensor shape mismatch");
970	    }
971	
972	    if (topK <= 0 || topK > vocabSize)
973	    {
974	        return;
975	    }
976	
977	    constexpr int32_t BLOCK_SIZE = 256;
978	    constexpr int32_t BLOCKS_PER_BEAM = 8;
979	
980	    // Setup workspace partitioning
981	    SamplingWorkspace ws;
982	    ws.setupWorkspaceForTopK(workspace.rawPointer(), workspace.getMemoryCapacity(), batchSize, vocabSize, topK);
983	
984	    // Create sampling parameters with temperature = 1.0 (no scaling applied to values)
985	    SamplingParams params(batchSize, vocabSize, 1.0f, topK);
986	
987	    // Stage 1: Find top-K elements (temperature=1.0 means no value transformation)
988	    dim3 grid1(batchSize * BLOCKS_PER_BEAM);
989	    dim3 block1(BLOCK_SIZE);
990	
991	    topKStage1<BLOCK_SIZE, BLOCKS_PER_BEAM><<<grid1, block1, 0, stream>>>(
992	        input.dataPointer<float>(), ws.topkTempLogits, ws.topkIndices, ws.topkValues, params);
993	
994	    // Stage 2: Select final top-K from 8*K candidates and return indices + raw values
995	    dim3 grid2(batchSize);
996	    dim3 block2(BLOCK_SIZE);
997	    size_t sharedMemSize = topK * sizeof(int32_t) + topK * sizeof(float);
998	
999	    float* topKValuesPtr = topKValues.has_value() ? topKValues.value().get().dataPointer<float>() : nullptr;
1000	    topKStage2ReturnAllTopK<BLOCK_SIZE><<<grid2, block2, sharedMemSize, stream>>>(ws.topkIndices, ws.topkValues,
1001	        topKIndices.dataPointer<int32_t>(), topKValuesPtr, batchSize, vocabSize, topK, BLOCKS_PER_BEAM);
1002	}
1003	
1004	// =======================================================================================
1005	// VOCABULARY MAPPING KERNEL
1006	// =======================================================================================
1007	
1008	/*!
1009	 * \brief CUDA kernel for mapping reduced vocabulary IDs to full vocabulary IDs (in-place)
1010	 *
1011	 * Each thread processes one element, performing a simple lookup operation:
1012	 * vocabIds[idx] = vocabMappingTable[vocabIds[idx]]
1013	 *
1014	 * The operation is performed in-place, reading and writing to the same memory location.
1015	 */
1016	__global__ void mapReducedVocabToFullVocabKernel(
1017	    int32_t* vocabIds, int32_t const* __restrict__ vocabMappingTable, int32_t totalElements)
1018	{
1019	    int32_t idx = static_cast<int32_t>(blockIdx.x * blockDim.x + threadIdx.x);
1020	
1021	    if (idx < totalElements)
1022	    {
1023	        // Read the reduced vocab ID, then overwrite with mapped full vocab ID
1024	        int32_t reducedId = vocabIds[idx];
1025	        vocabIds[idx] = vocabMappingTable[reducedId];
1026	    }
1027	}
1028	
1029	namespace
1030	{
1031	//! 256-byte alignment keeps the top-K temp storage that follows the log-softmax
1032	//! buffer inside the logprobs workspace CUB-friendly.
1033	constexpr size_t kLogprobsBufferAlignment = 256;
1034	
1035	size_t alignedLogSoftmaxBufferBytes(int32_t batchSize, int32_t vocabSize) noexcept
1036	{
1037	    size_t const bytes = static_cast<size_t>(batchSize) * vocabSize * sizeof(float);
1038	    return (bytes + kLogprobsBufferAlignment - 1) / kLogprobsBufferAlignment * kLogprobsBufferAlignment;
1039	}
1040	
1041	//! Tensor-level launcher for the numerically-stable log-softmax kernel.
1042	void logSoftmax(rt::Tensor const& logits, rt::Tensor& out, cudaStream_t stream)
1043	{
1044	    auto const shape = logits.getShape();
1045	    int32_t const batchSize = static_cast<int32_t>(shape[0]);
1046	    int32_t const vocabSize = static_cast<int32_t>(shape[1]);
1047	    constexpr int32_t LOG_SOFTMAX_BLOCK = 256;
1048	    softmaxKernelImpl<LOG_SOFTMAX_BLOCK, true><<<batchSize, LOG_SOFTMAX_BLOCK, 0, stream>>>(
1049	        logits.dataPointer<float>(), out.dataPointer<float>(), batchSize, vocabSize, 1.0f);
1050	}
1051	} // namespace
1052	
1053	size_t getExtractTopKLogprobsWorkspaceSize(int32_t batchSize, int32_t vocabSize, int32_t topK) noexcept
1054	{
1055	    // Log-softmax buffer up front (256B-aligned), selectAllTopK temp storage after it.
1056	    return alignedLogSoftmaxBufferBytes(batchSize, vocabSize)
1057	        + getSelectAllTopKWorkspaceSize(batchSize, vocabSize, topK);
1058	}
1059	
1060	void extractTopKLogprobs(rt::Tensor const& logits, rt::Tensor& logprobsValues, rt::Tensor& logprobsIndices,
1061	    int32_t topK, rt::Tensor& workspace, cudaStream_t stream)
1062	{
1063	    check::check(logits.getDeviceType() == rt::DeviceType::kGPU
1064	            && logprobsValues.getDeviceType() == rt::DeviceType::kGPU
1065	            && logprobsIndices.getDeviceType() == rt::DeviceType::kGPU
1066	            && workspace.getDeviceType() == rt::DeviceType::kGPU,
1067	        "All tensors must be on GPU");
1068	
1069	    auto const inputShape = logits.getShape();
1070	    int32_t const batchSize = static_cast<int32_t>(inputShape[0]);
1071	    int32_t const vocabSize = static_cast<int32_t>(inputShape[1]);
1072	
1073	    // Carve the workspace: log-softmax buffer up front, top-K temp storage after it.
1074	    size_t const bufferBytes = alignedLogSoftmaxBufferBytes(batchSize, vocabSize);
1075	    check::check(static_cast<size_t>(workspace.getMemoryCapacity())
1076	            >= getExtractTopKLogprobsWorkspaceSize(batchSize, vocabSize, topK),
1077	        "Logprobs workspace too small; size it with getExtractTopKLogprobsWorkspaceSize()");
1078	    int8_t* const wsBase = workspace.dataPointer<int8_t>();
1079	    rt::Tensor logSoftmaxOut(wsBase, {batchSize, vocabSize}, rt::DeviceType::kGPU, nvinfer1::DataType::kFLOAT);
1080	    rt::Tensor topKWorkspace(wsBase + bufferBytes,
1081	        {static_cast<int64_t>(workspace.getMemoryCapacity() - static_cast<int64_t>(bufferBytes))}, rt::DeviceType::kGPU,
1082	        nvinfer1::DataType::kINT8);
1083	
1084	    // Compute numerically-stable log-softmax, then select top-K (values are already log-probs).
1085	    logSoftmax(logits, logSoftmaxOut, stream);
1086	    selectAllTopK(logSoftmaxOut, rt::OptionalOutputTensor{std::ref(logprobsValues)}, logprobsIndices, topK,
1087	        topKWorkspace, stream);
1088	}
1089	
1090	namespace
1091	{
1092	// One block per output row; each thread copies a stride of vocab elements.
1093	__global__ void gatherSpecVerifyAcceptedLogitRowsKernel(float const* __restrict__ logits,
1094	    int32_t const* __restrict__ acceptedIndices, float* __restrict__ gathered, int32_t verifyTreeSize,
1095	    int32_t maxAcceptDepth, int32_t vocabSize)
1096	{
1097	    int32_t const outRow = blockIdx.x; // 0 .. batchSize*maxAcceptDepth-1
1098	    int32_t const batch = outRow / maxAcceptDepth;
1099	    int32_t const treePos = acceptedIndices[outRow];
1100	    int32_t const safeTreePos = min(max(treePos, 0), verifyTreeSize - 1);
1101	    int32_t const inRow = batch * verifyTreeSize + safeTreePos;
1102	
1103	    float const* src = logits + static_cast<ptrdiff_t>(inRow) * vocabSize;
1104	    float* dst = gathered + static_cast<ptrdiff_t>(outRow) * vocabSize;
1105	    for (int32_t v = threadIdx.x; v < vocabSize; v += blockDim.x)
1106	        dst[v] = src[v];
1107	}
1108	} // namespace
1109	
1110	void gatherSpecVerifyAcceptedLogitRows(rt::Tensor const& logits, rt::Tensor const& acceptedIndices,
1111	    rt::Tensor& gathered, int32_t batchSize, int32_t verifyTreeSize, int32_t maxAcceptDepth, int32_t vocabSize,
1112	    cudaStream_t stream)
1113	{
1114	    check::check(logits.getDeviceType() == rt::DeviceType::kGPU
1115	            && acceptedIndices.getDeviceType() == rt::DeviceType::kGPU
1116	            && gathered.getDeviceType() == rt::DeviceType::kGPU,
1117	        "All tensors must be on GPU");
1118	    int32_t const totalRows = batchSize * maxAcceptDepth;
1119	    constexpr int32_t kBlock = 256;
1120	    gatherSpecVerifyAcceptedLogitRowsKernel<<<totalRows, kBlock, 0, stream>>>(logits.dataPointer<float>(),
1121	        acceptedIndices.dataPointer<int32_t>(), gathered.dataPointer<float>(), verifyTreeSize, maxAcceptDepth,
1122	        vocabSize);
1123	}
1124	
1125	void mapReducedVocabToFullVocab(rt::Tensor& vocabIds, rt::Tensor const& vocabMappingTable, cudaStream_t stream)
1126	{
1127	    // Validate device types
1128	    check::check(
1129	        vocabIds.getDeviceType() == rt::DeviceType::kGPU && vocabMappingTable.getDeviceType() == rt::DeviceType::kGPU,
1130	        "All tensors must be on GPU");
1131	
1132	    // Validate data types
1133	    check::check(vocabIds.getDataType() == nvinfer1::DataType::kINT32
1134	            && vocabMappingTable.getDataType() == nvinfer1::DataType::kINT32,
1135	        "All tensors must have INT32 data type");
1136	
1137	    // Calculate total number of elements
1138	    int32_t totalElements = static_cast<int32_t>(vocabIds.getShape().volume());
1139	
1140	    if (totalElements == 0)
1141	    {
1142	        return; // Nothing to map
1143	    }
1144	
1145	    // Launch kernel
1146	    constexpr int32_t BLOCK_SIZE = 256;
1147	    int32_t numBlocks = (totalElements + BLOCK_SIZE - 1) / BLOCK_SIZE;
1148	
1149	    mapReducedVocabToFullVocabKernel<<<numBlocks, BLOCK_SIZE, 0, stream>>>(
1150	        vocabIds.dataPointer<int32_t>(), vocabMappingTable.dataPointer<int32_t>(), totalElements);
1151	}
