140	bool Tokenizer::parseTokenizerConfig(
141	    std::filesystem::path const& tokenizerFile, TokenToRanks& vocab, TokenToRanks& specialTokens)
142	{
143	    // Validate file size before reading
144	    if (!validateFileSize(tokenizerFile, limits::tokenizer::kMaxConfigFileSizeBytes))
145	    {
146	        return false;
147	    }
148	
149	    std::ifstream file(tokenizerFile);
150	    if (!file.is_open())
151	    {
152	        LOG_ERROR("Failed to open tokenizer.json: %s", tokenizerFile.c_str());
153	        return false;
154	    }
155	
156	    std::string content((std::istreambuf_iterator<char>(file)), std::istreambuf_iterator<char>());
157	    file.close();
158	
159	    Json jsonData;
160	    try
161	    {
162	        jsonData = Json::parse(content);
163	    }
164	    catch (Json::parse_error const& e)
165	    {
166	        LOG_ERROR("Failed to parse tokenizer.json: %s", e.what());
167	        return false;
168	    }
169	
170	    // Parse normalizer (applied before pre-tokenization)
171	    if (jsonData.contains("normalizer") && !jsonData["normalizer"].is_null())
172	    {
173	        auto const& normConfig = jsonData["normalizer"];
174	        std::string const normType = normConfig.value("type", "");
175	        if (normType == "Replace")
176	        {
177	            std::string pattern;
178	            if (normConfig.contains("pattern") && normConfig["pattern"].is_object())
179	            {
180	                pattern = normConfig["pattern"].value("String", "");
181	            }
182	            std::string content = normConfig.value("content", "");
183	            if (!pattern.empty())
184	            {
185	                mNormalizerReplacements.emplace_back(std::move(pattern), std::move(content));
186	                LOG_INFO("Tokenizer normalizer: Replace '%s' -> '%s'", mNormalizerReplacements.back().first.c_str(),
187	                    mNormalizerReplacements.back().second.c_str());
188	            }
189	        }
190	        else if (normType == "Sequence")
191	        {
192	            if (normConfig.contains("normalizers") && normConfig["normalizers"].is_array())
193	            {
194	                for (auto const& step : normConfig["normalizers"])
195	                {
196	                    std::string const stepType = step.value("type", "");
197	                    if (stepType == "Replace" && step.contains("pattern") && step["pattern"].is_object())
198	                    {
199	                        std::string pattern = step["pattern"].value("String", "");
200	                        std::string content = step.value("content", "");
201	                        if (!pattern.empty())
202	                        {
203	                            mNormalizerReplacements.emplace_back(std::move(pattern), std::move(content));
204	                        }
205	                    }
206	                }
207	            }
208	        }
209	    }
210	
211	    // Parse decoder (applied after decoding tokens back to text)
212	    if (jsonData.contains("decoder") && !jsonData["decoder"].is_null())
213	    {
214	        auto const& decConfig = jsonData["decoder"];
215	        std::string const decType = decConfig.value("type", "");
216	        if (decType == "Replace")
217	        {
218	            std::string pattern;
219	            if (decConfig.contains("pattern") && decConfig["pattern"].is_object())
220	            {
221	                pattern = decConfig["pattern"].value("String", "");
222	            }
223	            std::string content = decConfig.value("content", "");
224	            if (!pattern.empty())
225	            {
226	                mDecoderReplacements.emplace_back(std::move(pattern), std::move(content));
227	            }
228	        }
229	        else if (decType == "Sequence")
230	        {
231	            if (decConfig.contains("decoders") && decConfig["decoders"].is_array())
232	            {
233	                for (auto const& step : decConfig["decoders"])
234	                {
235	                    std::string const stepType = step.value("type", "");
236	                    if (stepType == "Replace" && step.contains("pattern") && step["pattern"].is_object())
237	                    {
238	                        std::string pattern = step["pattern"].value("String", "");
