287	    // Load special tokens from tokenizer.json
288	    if (!loadSpecialTokens(jsonData, specialTokens))
289	    {
290	        LOG_WARNING("Failed to load special tokens from tokenizer.json");
291	    }
292	
293	    // Create token encoder with byte_fallback support if configured
294	    mTokenEncoder = std::make_unique<TokenEncoder>(encoderType);
295	    bool byteFallback = jsonData["model"].value("byte_fallback", false);
296	    if (byteFallback)
297	    {
298	        mTokenEncoder->setByteFallback(true);
299	    }
300	
301	    // Load explicit BPE merges only for SentencePiece-style tokenizers (byte_fallback=true).
302	    // These tokenizers (e.g. Gemma) define merge order independently of vocab rank.
303	    // Tiktoken-style tokenizers (e.g. Qwen) have merges in tokenizer.json but use vocab rank
304	    // for merge ordering — loading merge priorities would break their tokenization.
305	    if (byteFallback && jsonData["model"].contains("merges") && jsonData["model"]["merges"].is_array())
306	    {
307	        auto const& mergesArray = jsonData["model"]["merges"];
308	        if (!mergesArray.empty())
309	        {
310	            std::unordered_map<std::string, Rank> mergePriorities;
311	            mergePriorities.reserve(mergesArray.size());
312	
313	            for (size_t i = 0; i < mergesArray.size(); ++i)
314	            {
315	                std::string left, right;
316	                if (mergesArray[i].is_string())
317	                {
318	                    // Format: "tokenA tokenB" — split on first space
319	                    std::string const& mergeStr = mergesArray[i].get_ref<std::string const&>();
320	                    auto spacePos = mergeStr.find(' ');
321	                    if (spacePos == std::string::npos)
322	                    {
323	                        LOG_WARNING("Invalid merge entry at index %zu: '%s'", i, mergeStr.c_str());
324	                        continue;
325	                    }
326	                    left = mergeStr.substr(0, spacePos);
327	                    right = mergeStr.substr(spacePos + 1);
328	                }
329	                else if (mergesArray[i].is_array() && mergesArray[i].size() == 2 && mergesArray[i][0].is_string()
330	                    && mergesArray[i][1].is_string())
331	                {
332	                    // Format: ["tokenA", "tokenB"]
333	                    left = mergesArray[i][0].get<std::string>();
334	                    right = mergesArray[i][1].get<std::string>();
335	                }
336	                else
337	                {
338	                    LOG_WARNING("Unrecognized merge entry format at index %zu", i);
339	                    continue;
340	                }
341	                // Use null-byte separator to avoid ambiguity when different (left, right) pairs
342	                // produce the same concatenation (e.g. "▁th"+"e" vs "▁t"+"he" both → "▁the").
343	                std::string key = left;
344	                key += '\0';
345	                key += right;
346	                mergePriorities[std::move(key)] = static_cast<Rank>(i);
347	            }
348	
349	            LOG_INFO("Loaded %zu BPE merge priorities", mergePriorities.size());
350	            mTokenEncoder->setMergePriorities(std::move(mergePriorities));
351	        }
352	    }
353	
354	    return true;
355	}
