357	bool Tokenizer::parseSpecialTokenConfig(std::filesystem::path const& configFile, TokenToRanks& specialTokens)
358	{
359	    // Validate file size before reading
360	    if (!validateFileSize(configFile, limits::tokenizer::kMaxConfigFileSizeBytes))
361	    {
362	        return false;
363	    }
364	
365	    std::ifstream file(configFile);
366	    if (!file.is_open())
367	    {
368	        LOG_ERROR("Failed to open tokenizer_config.json: %s", configFile.c_str());
369	        return false;
370	    }
371	
372	    std::string content((std::istreambuf_iterator<char>(file)), std::istreambuf_iterator<char>());
373	    file.close();
374	
375	    Json jsonConfig;
376	    try
377	    {
378	        jsonConfig = Json::parse(content);
379	    }
380	    catch (Json::parse_error const& e)
381	    {
382	        LOG_ERROR("Failed to parse tokenizer_config.json: %s", e.what());
383	        return false;
384	    }
385	
386	    // Load special tokens from tokenizer_config.json
387	    if (!loadSpecialTokens(jsonConfig, specialTokens))
388	    {
389	        LOG_WARNING("Failed to load special tokens from tokenizer_config.json");
390	    }
391	
392	    // Parse special token IDs
393	    auto parseSpecialToken = [&specialTokens](Json const& config, std::string const& field) -> Rank {
394	        if (!config.contains(field))
395	        {
396	            return -1;
397	        }
398	
399	        if (config[field].is_string())
400	        {
401	            std::string token = config[field].get<std::string>();
402	            auto it = specialTokens.find(token);
403	            if (it != specialTokens.end())
404	            {
405	                return it->second;
406	            }
407	            LOG_WARNING("Special token '%s' not found in vocabulary", token.c_str());
408	            return -1;
409	        }
410	        else if (config[field].is_object() && config[field].contains("content"))
411	        {
412	            std::string token = config[field]["content"].get<std::string>();
413	            auto it = specialTokens.find(token);
414	            if (it != specialTokens.end())
415	            {
416	                return it->second;
417	            }
418	            LOG_WARNING("Special token '%s' not found in vocabulary", token.c_str());
419	            return -1;
420	        }
421	
422	        return -1;
423	    };
424	
425	    mBosId = parseSpecialToken(jsonConfig, "bos_token");
426	    mEosId = parseSpecialToken(jsonConfig, "eos_token");
427	    mPadId = parseSpecialToken(jsonConfig, "pad_token");
428	    mUnkId = parseSpecialToken(jsonConfig, "unk_token");
429	    mImgContextId = parseSpecialToken(jsonConfig, "context_image_token");
430	
431	    return true;
432	}
