434	std::unique_ptr<PreTokenizer> Tokenizer::createPreTokenizer(Json const& preTokenizerConfig)
435	{
436	    // Handle sequence of pretokenizers
437	    if (preTokenizerConfig.contains("pretokenizers") && preTokenizerConfig["pretokenizers"].is_array())
438	    {
439	        auto sequence = std::make_unique<Sequence>();
440	
441	        for (auto const& step : preTokenizerConfig["pretokenizers"])
442	        {
443	            if (step.contains("type") && step["type"].is_string())
444	            {
445	                std::string type = step["type"].get<std::string>();
446	
447	                if (type == "Split" && step.contains("pattern"))
448	                {
449	                    // Handle Split with Regex pattern
450	                    if (step["pattern"].is_object() && step["pattern"].contains("Regex"))
451	                    {
452	                        std::string pattern = step["pattern"]["Regex"].get<std::string>();
453	                        std::string normalizedPattern = normalizeRegex(pattern);
454	                        sequence->addStep(std::make_unique<RegexSplit>(normalizedPattern));
455	                    }
456	                }
457	            }
458	        }
459	
460	        return sequence;
461	    }
462	
463	    // Handle single pretokenizer
464	    if (preTokenizerConfig.contains("type") && preTokenizerConfig["type"].is_string())
465	    {
466	        std::string type = preTokenizerConfig["type"].get<std::string>();
467	
468	        if (type == "Split" && preTokenizerConfig.contains("pattern"))
469	        {
470	            if (preTokenizerConfig["pattern"].is_object() && preTokenizerConfig["pattern"].contains("Regex"))
471	            {
472	                std::string pattern = preTokenizerConfig["pattern"]["Regex"].get<std::string>();
473	                std::string normalizedPattern = normalizeRegex(pattern);
474	                return std::make_unique<RegexSplit>(normalizedPattern);
475	            }
476	        }
477	        else if (type == "Regex" && preTokenizerConfig.contains("pattern"))
478	        {
479	            std::string pattern = preTokenizerConfig["pattern"].get<std::string>();
480	            std::string normalizedPattern = normalizeRegex(pattern);
481	            return std::make_unique<RegexSplit>(normalizedPattern);
482	        }
483	    }
484	
485	    LOG_WARNING("Unknown pretokenizer configuration, using default sequence");
486	    return std::make_unique<Sequence>();
487	}
