489	TokenEncoder::Type Tokenizer::determineEncoderType(Json const& modelConfig)
490	{
491	    if (modelConfig.contains("type") && modelConfig["type"].is_string())
492	    {
493	        std::string type = modelConfig["type"].get<std::string>();
494	
495	        if (type == "BPE")
496	        {
497	            return TokenEncoder::BPE;
498	        }
499	        else if (type == "Unigram")
500	        {
501	            return TokenEncoder::SENTENCEPIECE;
502	        }
503	        else if (type == "WordPiece")
504	        {
505	            return TokenEncoder::WORDPIECE;
506	        }
507	    }
508	
509	    LOG_WARNING("Unknown or missing model type, defaulting to BPE");
510	    return TokenEncoder::BPE;
511	}
