513	bool Tokenizer::loadVocabulary(Json const& modelConfig, TokenToRanks& vocab)
514	{
515	    if (!modelConfig.contains("vocab") || !modelConfig["vocab"].is_object())
516	    {
517	        LOG_ERROR("No vocabulary found in model configuration");
518	        return false;
519	    }
520	
521	    // Byte-fallback tokenizers (SentencePiece-style, e.g. Gemma) store vocab keys as raw
522	    // characters. Do NOT apply GPT-2 byte-to-unicode decoding, which would cause collisions
523	    // (e.g. raw '\n' → id 107 and 'Ċ' → id 247723 both decode to '\n').
524	    bool const isByteFallback = modelConfig.contains("byte_fallback") && modelConfig["byte_fallback"].get<bool>();
525	
526	    for (auto const& [hfToken, rank] : modelConfig["vocab"].items())
527	    {
528	        if (rank.is_number_integer())
529	        {
530	            try
531	            {
532	                std::string token = isByteFallback ? hfToken : decodeHFTokenToNormal(hfToken);
533	                vocab[token] = rank.get<Rank>();
534	            }
535	            catch (std::exception const& e)
536	            {
537	                LOG_WARNING("Failed to process vocabulary token '%s': %s", hfToken.c_str(), e.what());
538	            }
539	        }
540	    }
541	
542	    if (vocab.empty())
543	    {
544	        LOG_ERROR("No valid vocabulary tokens loaded");
545	        return false;
546	    }
547	
548	    LOG_INFO("Loaded %zu vocabulary tokens", vocab.size());
549	    return true;
550	}
