552	bool Tokenizer::loadSpecialTokens(Json const& tokenizerConfig, TokenToRanks& specialTokens)
553	{
554	    // Load from tokenizer.json added_tokens
555	    if (tokenizerConfig.contains("added_tokens") && tokenizerConfig["added_tokens"].is_array())
556	    {
557	        for (auto const& token : tokenizerConfig["added_tokens"])
558	        {
559	            if (token.contains("id") && token.contains("content") && token["id"].is_number_integer()
560	                && token["content"].is_string())
561	            {
562	                try
563	                {
564	                    Rank specialId = token["id"].get<Rank>();
565	                    std::string content = token["content"].get<std::string>();
566	
567	                    if (!content.empty())
568	                    {
569	                        specialTokens[content] = specialId;
570	                    }
571	                }
572	                catch (std::exception const& e)
573	                {
574	                    LOG_WARNING("Failed to parse added token: %s", e.what());
575	                }
576	            }
577	        }
578	    }
579	    // Also try to load additional special tokens from added_tokens_decoder
580	    if (tokenizerConfig.contains("added_tokens_decoder") && tokenizerConfig["added_tokens_decoder"].is_object())
581	    {
582	        for (auto const& [idStr, tokenData] : tokenizerConfig["added_tokens_decoder"].items())
583	        {
584	            if (tokenData.contains("content") && tokenData["content"].is_string())
585	            {
586	                try
587	                {
588	                    Rank specialId = std::stoi(idStr);
589	                    std::string content = tokenData["content"].get<std::string>();
590	
591	                    if (!content.empty())
592	                    {
593	                        specialTokens[content] = specialId;
594	                    }
595	                }
596	                catch (std::exception const& e)
597	                {
598	                    LOG_WARNING("Failed to parse added token ID '%s': %s", idStr.c_str(), e.what());
599	                }
600	            }
601	        }
602	    }
603	    return !specialTokens.empty();
604	}
