606	std::vector<Rank> Tokenizer::encode(std::string const& text, bool addBos, bool addEos) const
607	{
608	    if (!mInitialized || !mPreTokenizer || !mTokenEncoder)
609	    {
610	        LOG_ERROR("Tokenizer not properly initialized");
611	        return {};
612	    }
613	
614	    // Validate input text size before any processing to prevent expensive operations on oversized input
615	    if (text.size() > limits::tokenizer::kMaxInputTextSizeBytes)
616	    {
617	        LOG_ERROR(
618	            "Input text too large (%zu bytes, max: %zu).", text.size(), limits::tokenizer::kMaxInputTextSizeBytes);
619	        return {};
620	    }
621	
622	    std::vector<Rank> output;
623	    output.reserve(text.size() + (addBos ? 1 : 0) + (addEos ? 1 : 0));
624	
625	    if (addBos)
626	    {
627	        appendBos(output);
628	    }
629	
630	    if (!text.empty())
631	    {
632	        // Partition text into special tokens and raw text segments using forward_list
633	        std::forward_list<textPartition> partitions;
634	        partitions.emplace_front(text, 0, text.length());
635	
636	        if (!partitionSpecialTokens(text, partitions))
637	        {
638	            LOG_ERROR("Failed to partition special tokens");
639	            return {};
640	        }
641	
642	        // Process each partition
643	        for (auto const& part : partitions)
644	        {
645	            if (part.type == TEXT_PART_SPECIAL_TOKEN)
646	            {
647	                output.push_back(part.token);
648	            }
649	            else
650	            {
651	                // Process raw text partition
652	                std::string piece = part.rawText.substr(part.offset, part.length);
653	
654	                // Apply normalizer replacements (e.g., space -> ▁ for SentencePiece-style tokenizers)
655	                for (auto const& [pattern, replacement] : mNormalizerReplacements)
656	                {
657	                    std::string::size_type pos = 0;
658	                    while ((pos = piece.find(pattern, pos)) != std::string::npos)
659	                    {
660	                        piece.replace(pos, pattern.size(), replacement);
661	                        pos += replacement.size();
662	                    }
663	                }
664	
665	                // Process through pretokenizer
666	                std::vector<std::string> pieces;
667	                try
668	                {
669	                    pieces = mPreTokenizer->process(piece);
670	                }
671	                catch (std::exception const& e)
672	                {
673	                    LOG_ERROR("Pretokenizer failed: %s", e.what());
674	                    return {};
675	                }
676	
677	                // Encode each piece
678	                for (auto const& subpiece : pieces)
679	                {
680	                    std::vector<Rank> pieceTokens;
681	                    if (!mTokenEncoder->encode(subpiece, pieceTokens))
682	                    {
683	                        LOG_ERROR("Failed to encode piece: %s", subpiece.c_str());
684	                        return {};
685	                    }
686	                    output.insert(output.end(), pieceTokens.begin(), pieceTokens.end());
687	                }
688	            }
689	        }
690	    }
691	
692	    if (addEos)
693	    {
694	        appendEos(output);
695	    }
696	
697	    return output;
698	}
699	
700	bool Tokenizer::partitionSpecialTokens(
701	    std::string const& text, std::forward_list<textPartition>& partitions) const noexcept
702	{
703	    try
704	    {
705	        for (auto const& [specialToken, specialId] : mSpecialTokensEncoder)
706	        {
707	            for (auto it = partitions.begin(); it != partitions.end(); ++it)
708	            {
709	                auto& part = (*it);
710	
711	                // if part not yet processed
712	                if (part.type == TEXT_PART_RAW_TEXT)
713	                {
714	                    auto& rawText = part.rawText;
715	                    auto baseOffset = part.offset;
716	                    auto baseLength = part.length;
717	
718	                    // find occurrences of specialToken in rawText
719	                    while (true)
720	                    {
721	                        auto match = rawText.find(specialToken, baseOffset);
722	                        if ((match == std::string::npos)
723	                            || (static_cast<int>(match + specialToken.length()) > (baseOffset + baseLength)))
724	                        {
725	                            break;
726	                        }
727	
728	                        auto basePos = std::distance(partitions.begin(), it);
729	
730	                        // insert left part
731	                        if (match > static_cast<size_t>(baseOffset))
732	                        {
733	                            partitions.emplace_after(it, rawText, baseOffset, match - baseOffset);
734	                            ++it;
735	                        }
736	
737	                        // insert special token
738	                        partitions.emplace_after(it, specialId);
739	                        ++it;
740	
741	                        // remove original part
742	                        if (basePos == 0)
743	                        {
744	                            partitions.erase_after(partitions.before_begin());
745	                        }
746	                        else
747	                        {
748	                            partitions.erase_after(std::next(partitions.begin(), (basePos - 1)));
749	                        }
750	
751	                        // insert right part and continue loop
752	                        if (match + specialToken.length() < static_cast<size_t>(baseOffset + baseLength))
753	                        {
754	                            int rightOffset = match + specialToken.length();
755	                            int rightLength = baseLength + baseOffset - (match + specialToken.length());
756	                            partitions.emplace_after(it, rawText, rightOffset, rightLength);
757	                            ++it;
758	
759	                            baseOffset = rightOffset;
760	                            baseLength = rightLength;
761	                        }
762	                        else
763	                        {
764	                            break;
765	                        }
766	                    }
767	                }
768	            }
769	        }
770	
771	        return true;
772	    }
773	    catch (std::exception const& e)
774	    {
775	        LOG_ERROR("Tokenizer::partitionSpecialTokens failed on text: %s", text.c_str());
776	        return false;
777	    }
778	}
779	
780	std::string Tokenizer::decode(std::vector<Rank> const& tokens, bool skipSpecialTokens) const
781	{
782	    if (!mInitialized || !mTokenEncoder)
783	    {
784	        LOG_ERROR("Tokenizer not properly initialized");
785	        return "";
786	    }
787	
788	    std::string raw;
789	    if (!mTokenEncoder->decode(tokens, raw, skipSpecialTokens))
790	    {
791	        LOG_ERROR("Failed to decode tokens");
792	        return "";
793	    }
794	
795	    // Apply ByteFallback decoding: convert <0xNN> sequences to actual bytes.
796	    // SentencePiece byte_fallback tokenizers store individual byte tokens as "<0xNN>"
797	    // in the vocabulary. The ByteFallback decoder step converts them back to raw bytes.
798	    if (mByteFallbackDecode)
799	    {
800	        std::string decoded;
801	        decoded.reserve(raw.size());
802	        size_t i = 0;
803	        while (i < raw.size())
804	        {
805	            // Match pattern: <0xNN> where NN is exactly 2 hex digits
806	            if (i + 5 < raw.size() && raw[i] == '<' && raw[i + 1] == '0' && raw[i + 2] == 'x' && raw[i + 5] == '>')
807	            {
808	                char hi = raw[i + 3];
809	                char lo = raw[i + 4];
810	                int hiVal = hexCharToInt(hi);
811	                int loVal = hexCharToInt(lo);
812	                if (hiVal >= 0 && loVal >= 0)
813	                {
814	                    decoded.push_back(static_cast<char>((hiVal << 4) | loVal));
815	                    i += 6;
816	                    continue;
817	                }
818	            }
819	            decoded.push_back(raw[i]);
820	            ++i;
821	        }
822	        raw = std::move(decoded);
823	    }
824	
825	    // Apply decoder replacements (reverse of normalizer, e.g., ▁ -> space)
826	    for (auto const& [pattern, replacement] : mDecoderReplacements)
827	    {
828	        std::string::size_type pos = 0;
829	        while ((pos = raw.find(pattern, pos)) != std::string::npos)
830	        {
831	            raw.replace(pos, pattern.size(), replacement);
832	            pos += replacement.size();
833	        }
834	    }
835	
836	    // Route through the UTF-8 sanitizer to guarantee well-formed output. This
837	    // is a single-shot decode, so any trailing incomplete bytes must surface
838	    // as U+FFFD rather than be held for a later call.
839	    std::string pending;
840	    std::string output = utf8::sanitizeUtf8Streaming(raw, pending);
841	    output.append(utf8::sanitizeUtf8Flush(pending));
842	    return output;
843	}
844	
845	std::string Tokenizer::idToPiece(Rank token, bool skipSpecialTokens) const
846	{
847	    if (!mInitialized || !mTokenEncoder)
848	    {
849	        return "";
850	    }
851	    // Special tokens: return empty when skipping, the textual content otherwise.
852	    if (mSpecialTokensDecoder.find(token) != mSpecialTokensDecoder.end())
853	    {
854	        if (skipSpecialTokens)
855	        {
856	            return "";
857	        }
858	        return mSpecialTokensDecoder.at(token);
859	    }
860	    std::string piece = mTokenEncoder->getRankToken(token);
861	
862	    // Apply ByteFallback: convert single <0xNN> piece to raw byte.
863	    // A byte-fallback token is exactly 6 chars: "<0xNN>"
864	    if (mByteFallbackDecode && piece.size() == 6 && piece[0] == '<' && piece[1] == '0' && piece[2] == 'x'
865	        && piece[5] == '>')
866	    {
867	        int hiVal = hexCharToInt(piece[3]);
868	        int loVal = hexCharToInt(piece[4]);
869	        if (hiVal >= 0 && loVal >= 0)
870	        {
871	            piece = std::string(1, static_cast<char>((hiVal << 4) | loVal));
872	        }
873	    }
874	
875	    // Apply decoder replacements (e.g., ▁ -> space)
876	    for (auto const& [pattern, replacement] : mDecoderReplacements)
877	    {
878	        std::string::size_type pos = 0;
879	        while ((pos = piece.find(pattern, pos)) != std::string::npos)
880	        {
881	            piece.replace(pos, pattern.size(), replacement);
882	            pos += replacement.size();
883	        }
884	    }
885	    return piece;
886	}
