888	std::string emitDelta(
889	    rt::SlotStreamState& s, Tokenizer const& tok, std::vector<int32_t> const& allTokenIds, bool skipSpecial)
890	{
891	    // Fast path: no new tokens and no bytes held — nothing to do.
892	    if (allTokenIds.size() == s.sentTokenCount && s.pendingBytes.empty())
893	    {
894	        return "";
895	    }
896	
897	    // Concatenate the piece bytes for every newly-arrived token. Raw bytes may
898	    // span multi-token UTF-8 codepoints or contain adversarial isolated bytes;
899	    // sanitizeUtf8Streaming fixes both.
900	    std::string raw;
901	    for (size_t i = s.sentTokenCount; i < allTokenIds.size(); ++i)
902	    {
903	        raw.append(tok.idToPiece(allTokenIds[i], skipSpecial));
904	    }
905	    s.sentTokenCount = allTokenIds.size();
906	
907	    return utf8::sanitizeUtf8Streaming(raw, s.pendingBytes);
908	}
909	
910	std::string emitDeltaFlush(rt::SlotStreamState& s)
911	{
912	    return utf8::sanitizeUtf8Flush(s.pendingBytes);
913	}
