944	bool Tokenizer::loadChatTemplate(std::filesystem::path const& chatTemplateFile)
945	{
946	    if (!std::filesystem::exists(chatTemplateFile))
947	    {
948	        LOG_ERROR("Chat template file not found: %s", chatTemplateFile.c_str());
949	        return false;
950	    }
951	
952	    // Validate file size before reading
953	    if (!validateFileSize(chatTemplateFile, limits::tokenizer::kChatTemplateFileSizeBytes))
954	    {
955	        return false;
956	    }
957	
958	    std::ifstream file(chatTemplateFile);
959	    if (!file.is_open())
960	    {
961	        LOG_ERROR("Failed to open chat template file: %s", chatTemplateFile.c_str());
962	        return false;
963	    }
964	
965	    std::string content((std::istreambuf_iterator<char>(file)), std::istreambuf_iterator<char>());
966	    file.close();
967	
968	    Json jsonData;
969	    try
970	    {
971	        jsonData = Json::parse(content);
972	    }
973	    catch (Json::parse_error const& e)
974	    {
975	        LOG_ERROR("Failed to parse chat template JSON: %s", e.what());
976	        return false;
977	    }
978	
979	    try
980	    {
981	        // Parse model path
982	        mChatTemplate.modelPath = jsonData.value("model_path", mChatTemplate.modelPath);
983	
984	        // Parse roles,  which should contains [system, user, assistant]
985	        check::check(jsonData.contains("roles") && jsonData["roles"].is_object(),
986	            "Roles-field is required in chat template. And Shall be a JSON object.");
987	        for (auto const& [role, roleConfig] : jsonData["roles"].items())
988	        {
989	            ChatTemplateRole templateRole;
990	            templateRole.prefix = roleConfig.value("prefix", "");
991	            templateRole.suffix = roleConfig.value("suffix", "");
992	            mChatTemplate.roles[role] = templateRole;
993	        }
994	
995	        // Parse non-text content types place holder format string.
996	        if (jsonData.contains("content_types") && jsonData["content_types"].is_object())
997	        {
998	            for (auto const& [contentType, contentConfig] : jsonData["content_types"].items())
999	            {
1000	                ChatTemplateContentType templateContentType;
1001	                templateContentType.format = contentConfig.value("format", "");
1002	                if (templateContentType.format.empty())
1003	                {
1004	                    LOG_WARNING("Content type format is empty. Skip this content type: %s.", contentType.c_str());
1005	                    continue;
1006	                }
1007	                mChatTemplate.contentTypes[contentType] = templateContentType;
1008	            }
1009	        }
1010	
1011	        // Collect other fields from the chat template if exists.
1012	        mChatTemplate.generationPrompt = jsonData.value("generation_prompt", mChatTemplate.generationPrompt);
1013	        mChatTemplate.generationPromptThinking = jsonData.value("generation_prompt_thinking", "");
1014	        mChatTemplate.defaultSystemPrompt = jsonData.value("default_system_prompt", mChatTemplate.defaultSystemPrompt);
1015	        mChatTemplate.trimContent = jsonData.value("trim_content", false);
1016	        mChatTemplate.promptPrefix = jsonData.value("prompt_prefix", mChatTemplate.promptPrefix);
1017	    }
1018	    catch (std::exception const& e)
1019	    {
1020	        LOG_ERROR("Failed to parse chat template: %s", e.what());
1021	        return false;
1022	    }
1023	
1024	    LOG_INFO("Successfully loaded chat template from %s (for model: %s)", chatTemplateFile.c_str(),
1025	        mChatTemplate.modelPath.c_str());
1026	    return true;
1027	}
