1029	bool Tokenizer::applyChatTemplate(rt::LLMGenerationRequest::Request const& request,
1030	    rt::LLMGenerationRequest::FormattedRequest& formattedRequest, bool applyChatTemplate, bool addGenerationPrompt,
1031	    bool enableThinking) const
1032	{
1033	    if (request.messages.empty())
1034	    {
1035	        LOG_ERROR("Request shall contain at least one message to proceed with execution.");
1036	        return false;
1037	    }
1038	
1039	    std::string formattedPrefixSystemPrompt{};
1040	    std::string formattedCompleteRequest{};
1041	
1042	    // Extract system prompt from first message or use default
1043	    auto const& leadMessage = request.messages.front();
1044	    std::string systemPrompt{};
1045	    bool hasExplicitSystemMessage = false;
1046	
1047	    if (leadMessage.role == kRoleSystem)
1048	    {
1049	        hasExplicitSystemMessage = true;
1050	        for (auto const& content : leadMessage.contents)
1051	        {
1052	            if (content.type == "text")
1053	            {
1054	                systemPrompt += content.content;
1055	            }
1056	            else
1057	            {
1058	                LOG_WARNING("System message contents shall be all text. Find %s content type. Skip this content.",
1059	                    content.type.c_str());
1060	            }
1061	        }
1062	    }
1063	    else if (applyChatTemplate && !mChatTemplate.defaultSystemPrompt.empty())
1064	    {
1065	        hasExplicitSystemMessage = true;
1066	        systemPrompt = mChatTemplate.defaultSystemPrompt;
1067	    }
1068	
1069	    // Format system prompt (also format when there's an explicit system message with empty content,
1070	    // since some models like Qwen3-ASR expect the system role block even when empty)
1071	    if (!systemPrompt.empty() || (hasExplicitSystemMessage && applyChatTemplate))
1072	    {
1073	        if (applyChatTemplate)
1074	        {
1075	            auto roleIt = mChatTemplate.roles.find(kRoleSystem);
1076	            if (roleIt != mChatTemplate.roles.end())
1077	            {
1078	                formattedPrefixSystemPrompt
1079	                    = mChatTemplate.promptPrefix + roleIt->second.prefix + systemPrompt + roleIt->second.suffix;
1080	            }
1081	            else
1082	            {
1083	                LOG_WARNING("System role not found in chat template. Using raw content.");
1084	                formattedPrefixSystemPrompt = mChatTemplate.promptPrefix + systemPrompt;
1085	            }
1086	        }
1087	        else
1088	        {
1089	            formattedPrefixSystemPrompt = systemPrompt;
1090	        }
1091	        formattedCompleteRequest = formattedPrefixSystemPrompt;
1092	    }
1093	    else if (applyChatTemplate && !mChatTemplate.promptPrefix.empty())
1094	    {
1095	        formattedCompleteRequest = mChatTemplate.promptPrefix;
1096	    }
1097	
1098	    // Process messages
1099	    for (size_t i = 0; i < request.messages.size(); ++i)
1100	    {
1101	        auto const& message = request.messages[i];
1102	
1103	        if (message.role == kRoleSystem && i == 0)
1104	        {
1105	            continue;
1106	        }
1107	
1108	        auto roleIt = mChatTemplate.roles.find(message.role);
1109	        if (roleIt == mChatTemplate.roles.end())
1110	        {
1111	            LOG_WARNING("Unknown role: %s", message.role.c_str());
1112	            continue;
1113	        }
1114	
1115	        std::string formattedMessage;
1116	
1117	        // Add role prefix only in chat template mode
1118	        if (applyChatTemplate)
1119	        {
1120	            formattedMessage = roleIt->second.prefix;
1121	        }
1122	
1123	        // Process content items
1124	        for (auto const& contentItem : message.contents)
1125	        {
1126	            if (contentItem.type == "text")
1127	            {
1128	                if (mChatTemplate.trimContent)
1129	                {
1130	                    auto const& s = contentItem.content;
1131	                    auto start = s.find_first_not_of(" \t\n\r");
1132	                    auto end = s.find_last_not_of(" \t\n\r");
1133	                    if (start != std::string::npos)
1134	                    {
1135	                        formattedMessage += s.substr(start, end - start + 1);
1136	                    }
1137	                }
1138	                else
1139	                {
1140	                    formattedMessage += contentItem.content;
1141	                }
1142	            }
1143	            else if (contentItem.type == "trajectory")
1144	            {
1145	                if (request.pastTrajectory)
1146	                {
1147	                    formattedMessage += rt::kTrajHistoryStartStr;
1148	                    // One <|traj_history|> pad per binned axis value; Alpamayo1ActionRunner::preprocess replaces these
1149	                    // with discrete trajectory tokens after encode().
1150	                    size_t const numPadTokens = 3 * request.pastTrajectory->size();
1151	                    for (size_t k = 0; k < numPadTokens; ++k)
1152	                    {
1153	                        formattedMessage += rt::kTrajHistoryPadStr;
1154	                    }
1155	                    formattedMessage += rt::kTrajHistoryEndStr;
1156	                }
1157	                else
1158	                {
1159	                    LOG_WARNING("Content type 'trajectory' has no request.pastTrajectory; skipping.");
1160	                }
1161	            }
1162	            else
1163	            {
1164	                // Get content type format
1165	                auto contentTypeIt = mChatTemplate.contentTypes.find(contentItem.type);
1166	                if (contentTypeIt != mChatTemplate.contentTypes.end())
1167	                {
1168	                    formattedMessage += contentTypeIt->second.format;
1169	                }
1170	                else
1171	                {
1172	                    LOG_WARNING("Unknown content type: %s", contentItem.type.c_str());
1173	                }
1174	            }
1175	        }
1176	
1177	        // Add role suffix only in chat template mode
1178	        if (applyChatTemplate)
1179	        {
1180	            formattedMessage += roleIt->second.suffix;
1181	        }
1182	
1183	        formattedCompleteRequest += formattedMessage;
1184	    }
1185	
1186	    // Add generation prompt (only in chat template mode)
1187	    if (applyChatTemplate && addGenerationPrompt)
1188	    {
1189	        if (enableThinking && !mChatTemplate.generationPromptThinking.empty())
1190	        {
1191	            formattedCompleteRequest += mChatTemplate.generationPromptThinking;
1192	        }
1193	        else if (!mChatTemplate.generationPrompt.empty())
1194	        {
1195	            formattedCompleteRequest += mChatTemplate.generationPrompt;
1196	        }
1197	    }
1198	
1199	    formattedRequest.formattedSystemPrompt = formattedPrefixSystemPrompt;
1200	    formattedRequest.formattedCompleteRequest = formattedCompleteRequest;
1201	    return true;
1202	}
1203	
1204	} // namespace tokenizer
1205	} // namespace trt_edgellm
