57	    // Generate deterministic test logits (FP32 only)
58	    void generateTestLogits(
59	        rt::Tensor& logitsTensor, std::vector<std::vector<float>>& hostLogits, int batchSize, int vocabSize)
60	    {
61	        hostLogits.resize(batchSize);
62	        std::vector<float> flatHostLogits(batchSize * vocabSize);
63	
64	        // Generate deterministic but varied logits for testing using testUtils
65	        for (int b = 0; b < batchSize; ++b)
66	        {
67	            hostLogits[b].resize(vocabSize);
68	            uniformFloatInitialization(hostLogits[b], -2.0f, 2.0f);
69	
70	            // Add some structure to make testing more interesting
71	            if (vocabSize <= 20)
72	            {
73	                hostLogits[b][0] += 3.0f; // Make token 0 very likely
74	                hostLogits[b][1] += 2.0f; // Make token 1 second most likely
75	                for (int v = 0; v < 5; ++v)
76	                {
77	                    hostLogits[b][v] += 1.0f; // Make first 5 tokens more likely
78	                }
79	            }
80	            else
81	            {
82	                hostLogits[b][0] += 5.0f; // Make token 0 very likely
83	                for (int v = 0; v < 10; ++v)
84	                {
85	                    hostLogits[b][v] += 1.0f; // Make first 10 tokens more likely
86	                }
87	            }
88	
89	            // Ensure minimum differences between logits to prevent numerical instability
90	            std::sort(hostLogits[b].begin(), hostLogits[b].end(), std::greater<float>());
91	            for (int v = 1; v < vocabSize; ++v)
92	            {
93	                if (std::abs(hostLogits[b][v] - hostLogits[b][v - 1]) < 0.01f)
94	                {
95	                    hostLogits[b][v] = hostLogits[b][v - 1] - 0.01f;
96	                }
97	            }
98	
99	            // Shuffle the logits to ensure we're not testing with sorted data
100	            std::random_device rd;
101	            std::mt19937 gen(rd());
102	            std::shuffle(hostLogits[b].begin(), hostLogits[b].end(), gen);
103	
104	            // Copy to flat array (FP32 only)
105	            for (int v = 0; v < vocabSize; ++v)
106	            {
107	                flatHostLogits[b * vocabSize + v] = hostLogits[b][v];
108	            }
109	        }
110	
111	        // Copy host data to device memory
112	        copyHostToDevice<float>(logitsTensor, flatHostLogits);
113	    }
