115	    // Validate sampling results (FP32 only)
116	    bool validateSamplingResults(std::vector<int32_t> const& gpuResults,
117	        std::vector<std::vector<float>> const& hostLogits, SamplingParams const& params)
118	    {
119	        bool allValid = true;
120	        for (int b = 0; b < static_cast<int>(gpuResults.size()); ++b)
121	        {
122	            std::set<int32_t> allowedTokens;
123	
124	            if (params.useTopK && params.useTopP)
125	            {
126	                // Combined top-k and top-p
127	                allowedTokens
128	                    = getCombinedAllowedTokensRef(hostLogits[b], params.topK, params.topP, params.temperature);
129	            }
130	            else if (params.useTopK)
131	            {
132	                // Top-k only
133	                allowedTokens = getTopKAllowedTokensRef(hostLogits[b], params.topK);
134	            }
135	            else if (params.useTopP)
136	            {
137	                // Top-p only
138	                allowedTokens = getTopPAllowedTokensRef(hostLogits[b], params.topP, params.temperature);
139	            }
140	
141	            // Check if token is in allowed set
142	            if (allowedTokens.count(gpuResults[b]) == 0)
143	            {
144	                // Output detailed debug info without throwing
145	                std::cout << "=== SAMPLING VALIDATION FAILED ===" << std::endl;
146	                std::cout << "Batch " << b << ": Token " << gpuResults[b] << " not in allowed set" << std::endl;
147	                std::cout << "Allowed tokens: ";
148	                for (auto token : allowedTokens)
149	                {
150	                    std::cout << token << " ";
151	                }
152	                std::cout << std::endl;
153	                std::cout << "Logits for batch " << b << ": ";
154	                for (size_t i = 0; i < hostLogits[b].size(); ++i)
155	                {
156	                    std::cout << hostLogits[b][i];
157	                    if (i < hostLogits[b].size() - 1)
158	                        std::cout << ", ";
159	                }
160	                std::cout << std::endl;
161	                std::cout << "=================================" << std::endl;
162	
163	                allValid = false;
164	            }
165	        }
166	        return allValid;
167	    }
