169	    // Validate selectAllTopK results - checks indices and raw values (FP32 only)
170	    bool validateSelectAllTopKResults(std::vector<int32_t> const& gpuIndices, std::vector<float> const& gpuValues,
171	        std::vector<std::vector<float>> const& hostInput, int topK, int batchSize, bool checkValues)
172	    {
173	        bool allValid = true;
174	        for (int b = 0; b < batchSize; ++b)
175	        {
176	            // Get expected top-K elements (just raw values, no transformation)
177	            auto expectedResults = returnAllTopKReference(hostInput[b], topK);
178	
179	            // Check that we got the right number of elements
180	            int expectedSize = std::min(topK, static_cast<int>(hostInput[b].size()));
181	            if (static_cast<int>(expectedResults.size()) != expectedSize)
182	            {
183	                std::cout << "Wrong number of elements - expected " << expectedSize << ", got "
184	                          << expectedResults.size() << std::endl;
185	                allValid = false;
186	                continue;
187	            }
188	
189	            // Check that GPU indices match expected indices and values match
190	            for (int k = 0; k < expectedSize; ++k)
191	            {
192	                if (b * topK + k >= static_cast<int>(gpuIndices.size()))
193	                {
194	                    std::cout << "Index out of bounds for gpuIndices at batch " << b << " position " << k << std::endl;
195	                    allValid = false;
196	                    continue;
197	                }
198	
199	                int32_t gpuIdx = gpuIndices[b * topK + k];
200	
201	                // Check if the index is within valid range
202	                if (gpuIdx < 0 || gpuIdx >= static_cast<int>(hostInput[b].size()))
203	                {
204	                    std::cout << "Invalid index " << gpuIdx << " at batch " << b << " position " << k << std::endl;
205	                    allValid = false;
206	                    continue;
207	                }
208	
209	                // Check if this index is in the expected top-K results
210	                bool found = false;
211	                for (auto const& expected : expectedResults)
212	                {
213	                    if (expected.second == gpuIdx)
214	                    {
215	                        found = true;
216	                        break;
217	                    }
218	                }
219	
220	                if (!found)
221	                {
222	                    std::cout << "Index " << gpuIdx << " not found in expected top-K results at batch " << b
223	                              << " position " << k << std::endl;
224	                    allValid = false;
225	                }
226	
227	                // Check values if requested
228	                if (checkValues && !gpuValues.empty())
229	                {
230	                    float gpuValue = gpuValues[b * topK + k];
231	                    float expectedValue = hostInput[b][gpuIdx];
232	                    float relativeError = std::abs(gpuValue - expectedValue) / (std::abs(expectedValue) + 1e-6f);
233	
234	                    if (relativeError > 1e-5f)
235	                    {
236	                        std::cout << "Value mismatch at batch " << b << " position " << k << ": GPU=" << gpuValue
237	                                  << ", expected=" << expectedValue << std::endl;
238	                        allValid = false;
239	                    }
240	                }
241	            }
242	        }
243	        return allValid;
244	    }
245	};
